CREATE TABLE record_merge_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, kind VARCHAR NOT NULL, canonical_id BIGINT NOT NULL, before_data CLOB NOT NULL, after_data CLOB NOT NULL, merged_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
--;;
CREATE TABLE record_merge_alias (kind VARCHAR NOT NULL, old_id BIGINT NOT NULL, canonical_id BIGINT NOT NULL, merge_event_id BIGINT NOT NULL REFERENCES record_merge_event(id), PRIMARY KEY (kind, old_id));
--;;
CREATE TABLE record_merge_name_alias (kind VARCHAR NOT NULL, name_key VARCHAR NOT NULL, canonical_id BIGINT NOT NULL, PRIMARY KEY (kind, name_key));
